document.addEventListener("DOMContentLoaded", () => {
  const STORAGE_KEY = "anime-expeditions-template-editor-v4";
  const normalPose = document.querySelectorAll(".unit-page-pose-img img")[0];
  const shinyPose = document.querySelectorAll(".unit-page-pose-img img")[1];
  const toggle = document.querySelector(".unit-page-shiny-toggle");
  const poses = [...document.querySelectorAll(".unit-page-pose-img")];
  const passiveContainer = document.querySelector(".unit-page-passives-container");

  /* ---------- Shiny toggle ---------- */
  if (toggle && poses.length >= 2) {
    const setShiny = (shiny) => {
      toggle.classList.toggle("is-shiny", shiny);
      poses.forEach((pose, i) => pose.classList.toggle("is-active", shiny ? i === 1 : i === 0));
    };
    toggle.setAttribute("role", "button");
    toggle.setAttribute("tabindex", "0");
    toggle.setAttribute("aria-label", "Toggle shiny");
    toggle.addEventListener("click", () => setShiny(!toggle.classList.contains("is-shiny")));
    toggle.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggle.click();
      }
    });
    setShiny(false);
  }

  /* ---------- Editor toolbar ---------- */
  const toolbar = document.createElement("div");
  toolbar.className = "ae-editor-toolbar";
  toolbar.innerHTML = `
    <div class="ae-editor-title">Template Page Editor</div>
    <button type="button" data-action="add-ability">＋ Add Unit Ability</button>
    <button type="button" data-action="add-passive">＋ Add Unit Passive</button>
    <button type="button" data-action="delete-block" disabled>Delete Selected Box</button>
    <button type="button" data-action="edit-icons">✦ Edit Unit Icons</button>
    <button type="button" data-action="toggle-rarity">⇄ Rarity: Secret</button>
    <button type="button" data-action="main-image">Change Main Template Image</button>
    <button type="button" data-action="shiny-image">Change Shiny Image</button>
    <button type="button" data-action="save">Save</button>
    <button type="button" data-action="reset">Reset</button>
    <span class="ae-editor-hint">Double-click a text box to edit it.</span>
  `;
  document.body.appendChild(toolbar);

  /* ---------- Unit icon editor ----------
     Catalog is generated from every *Icon asset that appears in the supplied HTML.
  */
  const ICON_CATALOG = [{"id": "black_fire_icon", "name": "Black Fire Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/4/4b/Black_Fire_Icon.png"}, {"id": "crows_ring_icon", "name": "Crow's Ring Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/2/2a/Crow%27s_Ring_Icon.png/100px-Crow%27s_Ring_Icon.png"}, {"id": "damage_icon", "name": "Damage Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/4/42/Damage_Icon.png/20px-Damage_Icon.png"}, {"id": "flame_icon", "name": "Flame Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/a/a9/Flame_Icon.png"}, {"id": "gold_icon", "name": "Gold Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/2/26/Gold_Icon.png/100px-Gold_Icon.png"}, {"id": "illusion_icon", "name": "Illusion Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/2/2a/Illusion_Icon.png"}, {"id": "limited_icon", "name": "Limited Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/a/a1/Limited_Icon.png"}, {"id": "magical_icon", "name": "Magical Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/e/e9/Magical_Icon.png"}, {"id": "placement_limit_icon", "name": "Placement Limit Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/f/f4/Placement_Limit_Icon.png/20px-Placement_Limit_Icon.png"}, {"id": "range_icon", "name": "Range Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/0/08/Range_Icon.png/20px-Range_Icon.png"}, {"id": "spa_icon", "name": "SPA Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/0/08/SPA_Icon.png/20px-SPA_Icon.png"}, {"id": "shiny_hunter_icon", "name": "Shiny Hunter Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/4/4d/Shiny_Hunter_Icon.png"}, {"id": "sprite_(purple)_icon", "name": "Sprite (Purple) Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/b/b6/Sprite_%28Purple%29_Icon.png/100px-Sprite_%28Purple%29_Icon.png"}, {"id": "sprite_(rainbow)_icon", "name": "Sprite (Rainbow) Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/b/b3/Sprite_%28Rainbow%29_Icon.png/100px-Sprite_%28Rainbow%29_Icon.png"}, {"id": "sprite_(red)_icon", "name": "Sprite (Red) Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/5/5e/Sprite_%28Red%29_Icon.png/100px-Sprite_%28Red%29_Icon.png"}, {"id": "sprite_(yellow)_icon", "name": "Sprite (Yellow) Icon", "src": "https://static.wikitide.net/animeexpeditionswiki/thumb/7/7b/Sprite_%28Yellow%29_Icon.png/100px-Sprite_%28Yellow%29_Icon.png"}, {"id": "wind_swirl_icon", "name": "Wind Icon", "src": "data:image/png;base64,"}, {"id": "water_drop_icon", "name": "Water Icon", "src": "data:image/png;base64,"}, {"id": "earth_diamond_icon", "name": "Earth Icon", "src": "data:image/png;base64,"}, {"id": "fire_flame_icon", "name": "Fire Icon (Alt)", "src": "data:image/png;base64,"}, {"id": "storm_tornado_icon", "name": "Storm Icon", "src": "data:image/png;base64,"}, {"id": "light_sun_icon", "name": "Light Icon", "src": "data:image/png;base64,"}, {"id": "dark_crescent_icon", "name": "Dark Icon", "src": "data:image/png;base64,"}, {"id": "diamond_prism_icon", "name": "Prism Icon", "src": "data:image/png;base64,"}, {"id": "demon_trident_icon", "name": "Demon Icon", "src": "data:image/png;base64,"}, {"id": "magical_star_icon", "name": "Magical Icon (Alt)", "src": "data:image/png;base64,"}, {"id": "illusion_eye_icon", "name": "Illusion Icon (Alt)", "src": "data:image/png;base64,"}, {"id": "lightning_icon", "name": "Lightning Icon", "src": "data:image/png;base64,"}, {"id": "haste_clock_icon", "name": "Haste Icon", "src": "data:image/png;base64,"}, {"id": "magical_compass_purple_icon", "name": "Magical Icon (Purple)", "src": "data:image/png;base64,"}, {"id": "decrease_icon", "name": "Decrease Icon", "src": "data:image/png;base64,"}, {"id": "confusion_dice_icon", "name": "Confusion Icon", "src": "data:image/png;base64,"}, {"id": "bomb_icon", "name": "Bomb Icon", "src": "data:image/png;base64,"}, {"id": "speed_clock_icon", "name": "Speed Icon", "src": "data:image/png;base64,"}, {"id": "cosmic_orbit_icon", "name": "Cosmic Icon", "src": "data:image/png;base64,"}, {"id": "fire_alt2_icon", "name": "Fire Icon (Alt 2)", "src": "data:image/png;base64,"}, {"id": "bleed_icon", "name": "Bleed Icon", "src": "data:image/png;base64,"}, {"id": "phoenix_flame_icon", "name": "Phoenix Icon", "src": "data:image/png;base64,"}, {"id": "blue_flame_icon", "name": "Blue Fire Icon", "src": "data:image/png;base64,"}, {"id": "rotate_cycle_icon", "name": "Rotate Icon", "src": "data:image/png;base64,"}]
  const iconContainer = document.querySelector(".unit-page-icon-container");
  let iconEditTarget = null;

  function iconLabel(src) {
    const file = decodeURIComponent(src.split("/").pop() || "");
    return file.replace(/^\d+px-/, "").replace(/\.[^.]+$/, "").replace(/_Icon$/, "").replace(/_/g, " ");
  }

  function makeUnitIcon(item) {
    const wrapper = document.createElement("div");
    wrapper.className = "unit-page-icon gradient-image ae-unit-icon-editable";
    wrapper.dataset.iconId = item.id;
    wrapper.title = `Click to change ${item.name}`;
    const img = document.createElement("img");
    img.className = "mw-file-element";
    img.src = item.src;
    img.alt = item.name;
    wrapper.appendChild(img);
    wrapper.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openIconPicker(wrapper);
    });
    return wrapper;
  }

  function currentIcons() {
    if (!iconContainer) return [];
    return [...iconContainer.querySelectorAll(":scope > .unit-page-icon")].map(el => ({
      id: el.dataset.iconId || "",
      src: el.querySelector("img")?.src || "",
      name: el.querySelector("img")?.alt || iconLabel(el.querySelector("img")?.src || "")
    }));
  }

  function persistIcons() {
    saveState();
  }

  function openIconPicker(target) {
    iconEditTarget = target || null;
    let modal = document.querySelector(".ae-icon-modal");
    if (modal) modal.remove();

    modal = document.createElement("div");
    modal.className = "ae-icon-modal";
    modal.innerHTML = `
      <div class="ae-icon-modal-card">
        <div class="ae-icon-modal-head">
          <div>
            <div class="ae-icon-modal-title">Unit Icons</div>
            <div class="ae-icon-modal-subtitle">Choose an icon from the assets found in your supplied HTML.</div>
          </div>
          <button type="button" class="ae-icon-close">×</button>
        </div>
        <input class="ae-icon-search" type="search" placeholder="Search icons...">
        <div class="ae-icon-modal-body">
          <section class="ae-icon-section">
            <div class="ae-icon-section-title">Current icons</div>
            <div class="ae-current-icons"></div>
          </section>
          <section class="ae-icon-section">
            <div class="ae-icon-section-title">Available icons</div>
            <div class="ae-icon-grid"></div>
          </section>
        </div>
        <div class="ae-icon-modal-foot">
          <button type="button" class="ae-icon-add">＋ Add Icon</button>
          <button type="button" class="ae-icon-done">Done</button>
        </div>
      </div>`;
    document.body.appendChild(modal);

    const grid = modal.querySelector(".ae-icon-grid");
    const current = modal.querySelector(".ae-current-icons");
    const search = modal.querySelector(".ae-icon-search");
    let adding = false;

    function renderCurrent() {
      current.innerHTML = "";
      if (!iconContainer) return;
      [...iconContainer.querySelectorAll(":scope > .unit-page-icon")].forEach((el, index) => {
        const item = document.createElement("div");
        item.className = "ae-current-icon";
        const img = el.querySelector("img")?.cloneNode(true);
        const name = document.createElement("span");
        name.textContent = el.querySelector("img")?.alt || `Icon ${index+1}`;
        const remove = document.createElement("button");
        remove.type = "button";
        remove.className = "ae-current-remove";
        remove.textContent = "×";
        remove.title = "Remove icon";
        item.append(img, name, remove);
        item.addEventListener("click", (e) => {
          if (e.target === remove) return;
          adding = false;
          iconEditTarget = el;
          search.focus();
        });
        remove.addEventListener("click", (e) => {
          e.stopPropagation();
          el.remove();
          renderCurrent();
          persistIcons();
        });
        current.appendChild(item);
      });
    }

    function renderGrid() {
      const q = search.value.trim().toLowerCase();
      grid.innerHTML = "";
      ICON_CATALOG.filter(item => item.name.toLowerCase().includes(q)).forEach(item => {
        const card = document.createElement("button");
        card.type = "button";
        card.className = "ae-icon-choice";
        card.innerHTML = `<img src="${item.src}" alt=""><span>${escapeHTML(item.name)}</span>`;
        card.addEventListener("click", () => {
          if (adding || !iconEditTarget || !iconEditTarget.isConnected) {
            if (!iconContainer) return;
            const newIcon = makeUnitIcon(item);
            iconContainer.appendChild(newIcon);
            iconEditTarget = newIcon;
            adding = false;
          } else {
            const old = iconEditTarget;
            const replacement = makeUnitIcon(item);
            old.replaceWith(replacement);
            iconEditTarget = replacement;
          }
          renderCurrent();
          persistIcons();
          showToast(`${item.name} selected`);
        });
        grid.appendChild(card);
      });
    }

    search.addEventListener("input", renderGrid);
    modal.querySelector(".ae-icon-add").addEventListener("click", () => {
      adding = true;
      iconEditTarget = null;
      showToast("Choose an icon to add");
    });
    modal.querySelector(".ae-icon-close").addEventListener("click", () => modal.remove());
    modal.querySelector(".ae-icon-done").addEventListener("click", () => modal.remove());
    modal.addEventListener("click", e => { if (e.target === modal) modal.remove(); });
    renderCurrent();
    renderGrid();
  }

  toolbar.querySelector('[data-action="edit-icons"]').addEventListener("click", () => openIconPicker(null));
  iconContainer?.querySelectorAll(":scope > .unit-page-icon").forEach((el, i) => {
    const img = el.querySelector("img");
    if (!img) return;
    const item = ICON_CATALOG.find(x => x.src === img.src || img.src.endsWith(x.src.split('/').pop()));
    el.dataset.iconId = item?.id || `initial-${i}`;
    el.classList.add("ae-unit-icon-editable");
    el.title = "Click to change this icon";
    el.addEventListener("click", e => { e.preventDefault(); e.stopPropagation(); openIconPicker(el); });
  });

  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.accept = "image/png,image/jpeg,image/webp,image/gif,image/avif";
  fileInput.hidden = true;
  document.body.appendChild(fileInput);

  let imageTarget = null;
  toolbar.querySelector('[data-action="main-image"]').addEventListener("click", () => {
    imageTarget = normalPose;
    fileInput.click();
  });
  toolbar.querySelector('[data-action="shiny-image"]').addEventListener("click", () => {
    imageTarget = shinyPose;
    fileInput.click();
  });
  fileInput.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    if (!file || !imageTarget) return;
    const reader = new FileReader();
    reader.onload = () => {
      imageTarget.src = reader.result;
      imageTarget.dataset.editorImage = reader.result;
      saveState();
      showToast("Image changed and saved");
    };
    reader.readAsDataURL(file);
    fileInput.value = "";
  });

  /* ---------- Text editing ---------- */
  const editable = [];
  const seen = new Set();
  let keyCounter = 0;

  const selectors = [
    ".mw-parser-output > p",
    ".unit-page-title",
    ".unit-page-rarity",
    ".unit-page-placement-limit",
    ".unit-page-passive-header",
    ".unit-page-passive-content",
    ".unit-page-upgrade-cost",
    ".unit-page-upgrade-stat",
    ".unit-page-upgrade-additions",
    ".up-attack-header",
    ".ae-container-header",
    ".ebox_Title-inner",
    ".ebox_amount"
  ];

  function registerEditable(el, key) {
    if (!el || seen.has(el)) return;
    seen.add(el);
    el.dataset.editorKey = key || `text-${keyCounter++}`;
    el.classList.add("ae-editable");
    el.title = "Double-click to edit";
    el.addEventListener("dblclick", (event) => {
      if (event.target.closest("button, input, textarea, .ae-delete-block")) return;
      event.preventDefault();
      event.stopPropagation();
      startEdit(el);
    });
    editable.push(el);
  }

  selectors.forEach((selector) => {
    document.querySelectorAll(selector).forEach((el) => {
      if (el.closest(".ae-editor-toolbar")) return;
      // For passive/ability headers, make the label and name separately editable.
      if (el.classList.contains("unit-page-passive-header") && el.closest(".unit-page-passive-block")) {
        const gradientLabel = el.querySelector(".gradient-text");
        if (gradientLabel) registerEditable(gradientLabel, null);
        const name = [...el.childNodes].find(n => n.nodeType === Node.TEXT_NODE && n.textContent.trim());
        if (name) {
          const span = document.createElement("span");
          span.className = "ae-header-name-editable";
          span.textContent = name.textContent.trim();
          name.replaceWith(span);
          registerEditable(span, null);
        }
      } else {
        registerEditable(el, null);
      }
    });
  });

  function registerBlockText(block) {
    block.querySelectorAll("[data-editable-part]").forEach((el) => registerEditable(el, null));
  }

  let activeEditEl = null;
  let activeEditFinish = null;

  function startEdit(el) {
    if (el.dataset.editing === "true") return;
    el.dataset.editing = "true";
    el.classList.add("ae-editing");
    const oldHTML = el.innerHTML;
    el.setAttribute("contenteditable", "true");
    el.setAttribute("spellcheck", "false");
    el.focus();

    const range = document.createRange();
    range.selectNodeContents(el);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);

    let finished = false;
    const finish = (save) => {
      if (finished) return;
      finished = true;
      if (!save) el.innerHTML = oldHTML;
      el.removeAttribute("contenteditable");
      el.removeAttribute("spellcheck");
      el.classList.remove("ae-editing");
      el.dataset.editing = "false";
      hideFormatToolbar();
      if (activeEditEl === el) {
        activeEditEl = null;
        activeEditFinish = null;
      }
      if (save) saveState();
    };

    activeEditEl = el;
    activeEditFinish = finish;

    el.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        finish(false);
      } else if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        e.preventDefault();
        finish(true);
        el.blur();
      }
    });
  }

  // Editing ends when clicking outside both the active field and the format toolbar.
  // (Not blur-based: opening a native color picker blurs the field but shouldn't end editing.)
  document.addEventListener("mousedown", (e) => {
    if (!activeEditEl) return;
    if (activeEditEl.contains(e.target)) return;
    if (formatToolbar.contains(e.target)) return;
    if (activeEditFinish) activeEditFinish(true);
  });

  /* ---------- Floating text-format toolbar ---------- */
  const formatToolbar = document.createElement("div");
  formatToolbar.className = "ae-format-toolbar";
  formatToolbar.innerHTML = `
    <button type="button" data-cmd="bold" title="Bold"><b>B</b></button>
    <button type="button" data-cmd="underline" title="Underline"><u>U</u></button>
    <span class="ae-format-sep"></span>
    <label class="ae-format-swatch" title="Text color">
      <input type="color" data-cmd="color" value="#ffffff">
    </label>
    <select data-cmd="weight" title="Font weight">
      <option value="">Weight</option>
      <option value="300">300</option>
      <option value="400">400</option>
      <option value="500">500</option>
      <option value="600">600</option>
      <option value="700">700</option>
      <option value="800">800</option>
      <option value="900">900</option>
    </select>
    <span class="ae-format-sep"></span>
    <label class="ae-format-swatch" title="Gradient start"><input type="color" data-cmd="gradient-a" value="#ff5fa2"></label>
    <label class="ae-format-swatch" title="Gradient end"><input type="color" data-cmd="gradient-b" value="#7a5cff"></label>
    <button type="button" data-cmd="gradient" title="Apply gradient to selection">Gradient</button>
    <span class="ae-format-sep"></span>
    <button type="button" data-cmd="clear" title="Clear formatting">Clear</button>
  `;
  document.body.appendChild(formatToolbar);

  let savedFormatRange = null;

  function saveFormatRange() {
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0 && !sel.isCollapsed) {
      savedFormatRange = sel.getRangeAt(0).cloneRange();
      return true;
    }
    return false;
  }

  function restoreFormatRange() {
    if (!savedFormatRange) return false;
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(savedFormatRange);
    return true;
  }

  function positionFormatToolbar() {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
    const rect = sel.getRangeAt(0).getBoundingClientRect();
    if (!rect || (rect.width === 0 && rect.height === 0)) return;
    const top = rect.top + window.scrollY - formatToolbar.offsetHeight - 10;
    const left = rect.left + window.scrollX + rect.width / 2 - formatToolbar.offsetWidth / 2;
    const clampedLeft = Math.min(Math.max(8, left), window.scrollX + document.documentElement.clientWidth - formatToolbar.offsetWidth - 8);
    formatToolbar.style.top = `${Math.max(8, top)}px`;
    formatToolbar.style.left = `${clampedLeft}px`;
  }

  function showFormatToolbar() {
    formatToolbar.classList.add("ae-format-toolbar-visible");
    positionFormatToolbar();
  }

  function hideFormatToolbar() {
    formatToolbar.classList.remove("ae-format-toolbar-visible");
  }

  document.addEventListener("selectionchange", () => {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) {
      if (!formatToolbar.contains(document.activeElement)) hideFormatToolbar();
      return;
    }
    const anchor = sel.anchorNode;
    const anchorEl = anchor && (anchor.nodeType === 1 ? anchor : anchor.parentElement);
    const editingEl = anchorEl ? anchorEl.closest('[contenteditable="true"].ae-editing') : null;
    if (editingEl) {
      saveFormatRange();
      showFormatToolbar();
    } else if (!formatToolbar.contains(document.activeElement)) {
      hideFormatToolbar();
    }
  });

  function applyStyleToSelection(applyFn) {
    if (!restoreFormatRange()) return;
    const sel = window.getSelection();
    const range = sel.getRangeAt(0);
    if (range.collapsed) return;

    const mergedStyle = {};

    // Collect styles from ANCESTOR format-spans that contain the whole selection
    // (e.g. re-selecting text that's already inside a gradient span to underline it) -
    // without this, the old ancestor gets left behind wrapping the new span, and its
    // transparent/gradient fill visually bleeds onto content that shouldn't have it.
    const consumedAncestors = [];
    let ancestorNode = range.commonAncestorContainer;
    if (ancestorNode.nodeType !== 1) ancestorNode = ancestorNode.parentElement;
    while (ancestorNode && ancestorNode.classList) {
      if (ancestorNode.classList.contains("ae-editing") || ancestorNode.hasAttribute?.("contenteditable")) break;
      if (ancestorNode.classList.contains("ae-format-span")) {
        for (let i = 0; i < ancestorNode.style.length; i++) {
          const prop = ancestorNode.style[i];
          if (!(prop in mergedStyle)) mergedStyle[prop] = ancestorNode.style.getPropertyValue(prop);
        }
        consumedAncestors.push(ancestorNode);
      }
      ancestorNode = ancestorNode.parentElement;
    }

    const extracted = range.extractContents();

    // Collect style properties from any format-spans within the selection (depth-first,
    // so outer/older spans don't clobber inner/newer ones that were applied more recently),
    // then unwrap them all so we end up with one flat span instead of nested ones.
    function collectAndUnwrap(node) {
      if (node.nodeType !== 1) return;
      const isFormatSpan = node.classList && node.classList.contains("ae-format-span");
      if (isFormatSpan) {
        for (let i = 0; i < node.style.length; i++) {
          const prop = node.style[i];
          if (!(prop in mergedStyle)) mergedStyle[prop] = node.style.getPropertyValue(prop);
        }
      }
      [...node.childNodes].forEach(collectAndUnwrap);
      if (isFormatSpan) {
        const parent = node.parentNode;
        while (node.firstChild) parent.insertBefore(node.firstChild, node);
        parent.removeChild(node);
      }
    }
    [...extracted.childNodes].forEach(collectAndUnwrap);

    const span = document.createElement("span");
    span.className = "ae-format-span";
    Object.entries(mergedStyle).forEach(([prop, value]) => span.style.setProperty(prop, value));
    span.appendChild(extracted);
    range.insertNode(span);

    // Innermost-first: pull the new span out from under any consumed ancestor so it
    // becomes a sibling, then drop the ancestor if that emptied it out entirely. If the
    // ancestor still has other (unselected) content, it's left in place so that content
    // keeps its original formatting.
    consumedAncestors.forEach((anc) => {
      if (!anc.isConnected) return;
      const parent = anc.parentNode;
      if (!parent) return;
      if (anc.contains(span)) parent.insertBefore(span, anc.nextSibling);
      if (anc.textContent === "") parent.removeChild(anc);
    });

    applyFn(span);

    const newRange = document.createRange();
    newRange.selectNodeContents(span);
    sel.removeAllRanges();
    sel.addRange(newRange);
    savedFormatRange = newRange.cloneRange();
    positionFormatToolbar();
    if (activeEditEl) saveState();
  }

  // Keep the field's selection alive when clicking toolbar buttons.
  formatToolbar.querySelectorAll("button").forEach((btn) => {
    btn.addEventListener("mousedown", (e) => e.preventDefault());
  });

  function isTransparentFill(span) {
    return span.style.color === "transparent" || span.style.webkitTextFillColor === "transparent";
  }

  function firstGradientColor(bgValue) {
    if (!bgValue) return null;
    const match = bgValue.match(/rgba?\([^)]+\)|#[0-9a-fA-F]{3,8}/);
    return match ? match[0] : null;
  }

  formatToolbar.querySelector('[data-cmd="bold"]').addEventListener("click", () => {
    applyStyleToSelection((span) => { span.style.fontWeight = "700"; });
  });

  formatToolbar.querySelector('[data-cmd="underline"]').addEventListener("click", () => {
    applyStyleToSelection((span) => {
      span.style.textDecoration = "underline";
      // currentColor (the default) is invisible on gradient/transparent-fill text, so
      // give the underline an explicit visible color that matches what's actually shown.
      if (isTransparentFill(span)) {
        span.style.textDecorationColor = firstGradientColor(span.style.background) || "#ffffff";
      } else {
        span.style.textDecorationColor = "";
      }
    });
  });

  formatToolbar.querySelector('[data-cmd="color"]').addEventListener("input", (e) => {
    const value = e.target.value;
    applyStyleToSelection((span) => {
      // A solid color replaces any gradient fill - they're mutually exclusive.
      span.style.background = "";
      span.style.webkitBackgroundClip = "";
      span.style.backgroundClip = "";
      span.style.webkitTextFillColor = "";
      span.style.color = value;
      if (span.style.textDecorationLine === "underline" || span.style.textDecoration.indexOf("underline") !== -1) {
        span.style.textDecorationColor = value;
      }
    });
  });

  formatToolbar.querySelector('[data-cmd="weight"]').addEventListener("mousedown", (e) => e.stopPropagation());
  formatToolbar.querySelector('[data-cmd="weight"]').addEventListener("change", (e) => {
    const value = e.target.value;
    e.target.value = "";
    if (!value) return;
    applyStyleToSelection((span) => { span.style.fontWeight = value; });
  });

  formatToolbar.querySelector('[data-cmd="gradient"]').addEventListener("click", () => {
    const colorA = formatToolbar.querySelector('[data-cmd="gradient-a"]').value;
    const colorB = formatToolbar.querySelector('[data-cmd="gradient-b"]').value;
    applyStyleToSelection((span) => {
      span.style.background = `linear-gradient(90deg, ${colorA}, ${colorB})`;
      span.style.webkitBackgroundClip = "text";
      span.style.backgroundClip = "text";
      span.style.color = "transparent";
      span.style.webkitTextFillColor = "transparent";
      if (span.style.textDecorationLine === "underline" || span.style.textDecoration.indexOf("underline") !== -1) {
        span.style.textDecorationColor = colorA;
      }
    });
  });

  formatToolbar.querySelector('[data-cmd="clear"]').addEventListener("click", () => {
    if (!restoreFormatRange()) return;
    const sel = window.getSelection();
    const range = sel.getRangeAt(0);
    const container = range.commonAncestorContainer.nodeType === 1
      ? range.commonAncestorContainer
      : range.commonAncestorContainer.parentElement;
    if (container) {
      const spans = [...container.querySelectorAll(".ae-format-span")].filter((s) => range.intersectsNode(s));
      spans.forEach((span) => {
        const parent = span.parentNode;
        if (!parent) return;
        while (span.firstChild) parent.insertBefore(span.firstChild, span);
        parent.removeChild(span);
      });
    }
    saveFormatRange();
    if (activeEditEl) saveState();
  });

  /* ---------- Ability / Passive builders ---------- */
  function createHeader(label, labelClass, name) {
    const header = document.createElement("div");
    header.className = "unit-page-passive-header";
    header.innerHTML = `<span class="gradient-text ${labelClass}" style="--deg:90deg;font-weight:800;letter-spacing:-1%;" data-editable-part>${escapeHTML(label)}</span><span class="ae-header-name-editable" data-editable-part>${escapeHTML(name)}</span>`;
    return header;
  }

  function createPassiveBlock() {
    const block = document.createElement("div");
    block.className = "unit-page-passive-block ae-generated-block";
    block.dataset.editorGenerated = "passive";
    block.appendChild(createHeader("Unit Passive", "c-passive", "New Passive"));
    const content = document.createElement("div");
    content.className = "unit-page-passive-content";
    content.dataset.editablePart = "";
    content.innerHTML = "Enter passive description here.";
    block.appendChild(content);
    addGeneratedBlock(block);
    return block;
  }

  function createAbilityBlock() {
    const block = document.createElement("div");
    block.className = "unit-page-passive-block ae-generated-block ae-ability-block";
    block.dataset.editorGenerated = "ability";
    block.appendChild(createHeader("Unit Ability", "c-purplink", "New Ability"));

    const content = document.createElement("div");
    content.className = "unit-page-passive-content";
    content.dataset.editablePart = "";
    content.innerHTML = `On activation:<br>- Enter ability description here<br>- Add another line here`;
    block.appendChild(content);

    const cooldowns = document.createElement("div");
    cooldowns.className = "ae-ability-cooldowns";
    cooldowns.innerHTML = `
      <span class="ae-cooldown-pill" data-editable-part>60s CD</span>
      <span class="ae-cooldown-pill" data-editable-part>Global Cooldown</span>
      <button type="button" class="ae-add-cooldown">＋ CD</button>
    `;
    block.appendChild(cooldowns);

    const unlock = document.createElement("div");
    unlock.className = "ae-ability-unlock";
    unlock.dataset.editablePart = "";
    unlock.textContent = "Ability unlocks on Upgrade 7!";
    block.appendChild(unlock);

    addGeneratedBlock(block);
    return block;
  }

  function addGeneratedBlock(block) {
    if (!passiveContainer) return;
    passiveContainer.appendChild(block);
    registerBlockText(block);
    block.querySelector(".ae-add-cooldown")?.addEventListener("click", (e) => {
      e.preventDefault();
      const pill = document.createElement("span");
      pill.className = "ae-cooldown-pill";
      pill.dataset.editablePart = "";
      pill.textContent = "New Cooldown";
      e.currentTarget.before(pill);
      registerEditable(pill, null);
      pill.dispatchEvent(new MouseEvent("dblclick", { bubbles: true }));
      saveState();
    });
    saveState();
    showToast(block.dataset.editorGenerated === "ability" ? "Unit Ability added" : "Unit Passive added");
    block.scrollIntoView({ behavior: "smooth", block: "center" });
  }

  toolbar.querySelector('[data-action="add-ability"]').addEventListener("click", () => createAbilityBlock());
  toolbar.querySelector('[data-action="add-passive"]').addEventListener("click", () => createPassiveBlock());

  /* ---------- Box selection + delete ---------- */
  let selectedBlock = null;
  const deleteBtn = toolbar.querySelector('[data-action="delete-block"]');

  function selectBlock(block) {
    if (selectedBlock === block) return;
    if (selectedBlock) selectedBlock.classList.remove("ae-block-selected");
    selectedBlock = block;
    if (selectedBlock) selectedBlock.classList.add("ae-block-selected");
    if (deleteBtn) deleteBtn.disabled = !selectedBlock;
  }

  if (passiveContainer) {
    passiveContainer.addEventListener("click", (e) => {
      if (e.target.closest("button")) return;
      const block = e.target.closest(".unit-page-passive-block");
      if (block) selectBlock(block);
    });
  }

  document.addEventListener("click", (e) => {
    if (!selectedBlock) return;
    if (e.target.closest(".unit-page-passive-block") || e.target.closest('[data-action="delete-block"]')) return;
    selectBlock(null);
  });

  deleteBtn?.addEventListener("click", () => {
    if (!selectedBlock) return;
    selectedBlock.remove();
    selectedBlock = null;
    deleteBtn.disabled = true;
    saveState();
    showToast("Box removed");
  });

  /* ---------- Rarity toggle ---------- */
  const RARITIES = {
    secret: { label: "Secret", cssClass: "c-secret" },
    mythic: { label: "Mythic", cssClass: "c-mythic" }
  };
  const rarityOrder = ["secret", "mythic"];
  const rarityBtn = toolbar.querySelector('[data-action="toggle-rarity"]');
  const rarityBadge = document.querySelector(".unit-page-rarity");
  const rarityInline = document.querySelector(".ae-rarity-inline");
  let currentRarity = "secret";

  function applyRarity(key) {
    const info = RARITIES[key];
    if (!info) return;
    currentRarity = key;
    [rarityBadge, rarityInline].forEach((el) => {
      if (!el) return;
      Object.values(RARITIES).forEach(r => el.classList.remove(r.cssClass));
      el.classList.add(info.cssClass);
      el.textContent = info.label;
    });
    if (rarityBtn) rarityBtn.textContent = `⇄ Rarity: ${info.label}`;
  }

  rarityBtn?.addEventListener("click", () => {
    const nextIndex = (rarityOrder.indexOf(currentRarity) + 1) % rarityOrder.length;
    applyRarity(rarityOrder[nextIndex]);
    saveState();
  });

  function escapeHTML(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }

  /* ---------- Persistence ---------- */
  function collectState() {
    const staticText = editable
      .filter(el => !el.closest(".ae-generated-block"))
      .map(el => ({ key: el.dataset.editorKey, html: el.innerHTML }));

    const generated = passiveContainer
      ? [...passiveContainer.querySelectorAll(":scope > .ae-generated-block")].map(block => block.outerHTML)
      : [];

    return {
      text: staticText,
      generated,
      normalImage: normalPose?.dataset.editorImage || "",
      shinyImage: shinyPose?.dataset.editorImage || "",
      icons: currentIcons(),
      rarity: currentRarity
    };
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(collectState()));
    } catch (error) {
      console.warn(error);
      showToast("Saved text, but an image may be too large for browser storage");
    }
  }

  function restoreState() {
    try {
      const data = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
      if (!data) return;

      // Restore generated ability/passive boxes first.
      if (passiveContainer && Array.isArray(data.generated)) {
        data.generated.forEach(html => {
          const temp = document.createElement("div");
          temp.innerHTML = html;
          const block = temp.firstElementChild;
          if (!block) return;
          passiveContainer.appendChild(block);
          registerBlockText(block);
          block.querySelector(".ae-add-cooldown")?.addEventListener("click", (e) => {
            const pill = document.createElement("span");
            pill.className = "ae-cooldown-pill";
            pill.dataset.editablePart = "";
            pill.textContent = "New Cooldown";
            e.currentTarget.before(pill);
            registerEditable(pill, null);
            pill.dispatchEvent(new MouseEvent("dblclick", { bubbles: true }));
          });
        });
      }

      const byKey = new Map(editable.map(el => [el.dataset.editorKey, el]));
      (data.text || []).forEach(entry => {
        const el = byKey.get(entry.key);
        if (el && typeof entry.html === "string") el.innerHTML = entry.html;
      });

      if (iconContainer && Array.isArray(data.icons)) {
        iconContainer.innerHTML = "";
        data.icons.forEach((item, i) => {
          const catalogItem = ICON_CATALOG.find(x => x.id === item.id) || item;
          const el = makeUnitIcon({id: catalogItem.id || `restored-${i}`, name: catalogItem.name || item.name || "Icon", src: catalogItem.src || item.src});
          iconContainer.appendChild(el);
        });
      }

      if (data.normalImage && normalPose) {
        normalPose.src = data.normalImage;
        normalPose.dataset.editorImage = data.normalImage;
      }
      if (data.shinyImage && shinyPose) {
        shinyPose.src = data.shinyImage;
        shinyPose.dataset.editorImage = data.shinyImage;
      }

      if (data.rarity && RARITIES[data.rarity]) {
        applyRarity(data.rarity);
      }
    } catch (error) {
      console.warn("Could not restore editor state", error);
    }
  }

  toolbar.querySelector('[data-action="save"]').addEventListener("click", () => {
    saveState();
    showToast("Changes saved");
  });
  toolbar.querySelector('[data-action="reset"]').addEventListener("click", () => {
    if (!confirm("Reset all text, ability/passive boxes, and image changes?")) return;
    localStorage.removeItem(STORAGE_KEY);
    location.reload();
  });

  restoreState();

  /* ---------- Mechanics modal ---------- */
  const overlay = document.querySelector(".overlay-backdrop-mask");
  const hide = () => {
    if (!overlay) return;
    overlay.classList.remove("is-visible");
    document.body.style.overflow = "";
  };
  const show = () => {
    if (!overlay) return;
    overlay.classList.add("is-visible");
    document.body.style.overflow = "hidden";
  };
  document.querySelectorAll("[data-mechanics], .unit-page-mechanics-button").forEach((button) => button.addEventListener("click", show));
  overlay?.addEventListener("click", (e) => { if (e.target === overlay) hide(); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape" && !document.querySelector("[contenteditable='true']")) hide(); });
  document.querySelectorAll('a[href="#"]').forEach((a) => a.addEventListener("click", (e) => e.preventDefault()));

  function showToast(message) {
    let toast = document.querySelector(".ae-editor-toast");
    if (!toast) {
      toast = document.createElement("div");
      toast.className = "ae-editor-toast";
      document.body.appendChild(toast);
    }
    toast.textContent = message;
    toast.classList.add("is-visible");
    clearTimeout(toast._timer);
    toast._timer = setTimeout(() => toast.classList.remove("is-visible"), 1800);
  }
});
